//! Exact registry-inception vectors generated by the pinned TypeScript reference.

use std::collections::BTreeMap;
use std::error::Error;

use keri_protocol::event::ConfigurationTrait;
use keri_protocol::prefix::IdentifierPrefix;
use keri_protocol::registry::{RegistryError, RegistryInceptionBuilder};
use serde::Deserialize;

const REFERENCE_SHA: &str = "91a04a5edd804425f42be75ffbf034f8d14e5cb2";
const FIXTURE: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/fixtures/keri-registry/v1.json"));

#[derive(Debug, Deserialize)]
struct Fixture {
    schema_version: u8,
    upstream: String,
    reference_sha: String,
    generated_on: String,
    sources: Vec<String>,
    provenance: Provenance,
    inceptions: BTreeMap<String, InceptionRecord>,
    random_nonce_shape: NonceShape,
    rejections: Vec<Rejection>,
    reference_quirks: Quirks,
}

#[derive(Debug, Deserialize)]
struct Provenance {
    issuer: String,
    nonce: String,
    note: String,
}

#[derive(Debug, Deserialize)]
struct InceptionRecord {
    args_note: Option<String>,
    raw: String,
    pre: String,
    said: Option<String>,
    size: usize,
    backer_threshold: Option<String>,
}

#[derive(Debug, Deserialize)]
struct NonceShape {
    length: usize,
    code: String,
    note: String,
}

#[derive(Debug, Deserialize)]
struct Rejection {
    name: String,
    note: String,
    reference_error_message: String,
}

#[derive(Debug, Deserialize)]
struct Quirks {
    non_numeric_toad_emits_nan: NanQuirk,
    string_toad_is_coerced: CoercionQuirk,
    backers_are_unvalidated: NoteQuirk,
    issuer_is_unvalidated: IssuerQuirk,
}

#[derive(Debug, Deserialize)]
struct NanQuirk {
    raw: String,
    backer_threshold: String,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct CoercionQuirk {
    identical: bool,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct NoteQuirk {
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct IssuerQuirk {
    accepted: bool,
    pre: String,
    note: String,
    rust_decision: String,
}

fn fixture() -> Result<Fixture, Box<dyn Error>> {
    Ok(serde_json::from_str(FIXTURE)?)
}

fn builder(fixture: &Fixture) -> Result<RegistryInceptionBuilder, Box<dyn Error>> {
    Ok(RegistryInceptionBuilder::new(
        IdentifierPrefix::from_qb64(&fixture.provenance.issuer)?,
        fixture.provenance.nonce.clone(),
    ))
}

fn backers(count: usize) -> Vec<String> {
    (0..count).map(|index| format!("backer-{index}")).collect()
}

#[test]
fn the_manifest_matches_the_pinned_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert!(fixture.upstream.contains("WebOfTrust/signify-ts"));
    assert_ne!(fixture.generated_on, "");
    assert!(fixture.sources.iter().any(|source| source.ends_with("vdring.ts")));
    assert_ne!(fixture.provenance.note, "");
    assert_eq!(fixture.inceptions.len(), 11);
    Ok(())
}

#[test]
fn every_inception_matches_byte_for_byte() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    for (name, expected) in &fixture.inceptions {
        let base = builder(&fixture)?;
        let built = match name.as_str() {
            "pinned_default" => base.backer_threshold(0).build(),
            "pinned_default_without_toad" => base.build(),
            "pinned_backer" => base.backers(vec!["a backer".to_owned()]).backer_threshold(1).build(),
            "pinned_backer_without_toad" => base.backers(vec!["a backer".to_owned()]).build(),
            "no_backers_trait" => base.configuration(vec![ConfigurationTrait::NoBackers]).build(),
            "all_traits" => base
                .configuration(vec![
                    ConfigurationTrait::EstablishmentOnly,
                    ConfigurationTrait::DoNotDelegate,
                    ConfigurationTrait::NoBackers,
                ])
                .build(),
            "three_backers_default_toad" => base.backers(backers(3)).build(),
            "three_backers_explicit_toad" => base.backers(backers(3)).backer_threshold(2).build(),
            "five_backers_default_toad" => base.backers(backers(5)).build(),
            "twelve_backers_hexadecimal_toad" => base.backers(backers(12)).backer_threshold(10).build(),
            "empty_nonce" => {
                RegistryInceptionBuilder::new(IdentifierPrefix::from_qb64(&fixture.provenance.issuer)?, "").build()
            }
            other => return Err(format!("unknown inception case {other:?}").into()),
        }
        .map_err(|error| format!("{name}: {error}"))?;

        assert_eq!(built.raw(), expected.raw.as_bytes(), "{name}");
        assert_eq!(built.identifier().qb64()?, expected.pre, "{name}");
        if let Some(said) = &expected.said {
            assert_eq!(built.said().qb64()?.as_str(), said, "{name}");
        }
        assert_eq!(built.raw().len(), expected.size, "{name}");
        if let Some(threshold) = &expected.backer_threshold {
            assert_eq!(built.sad().get_text("bt"), Some(threshold.as_str()), "{name}");
        }
        assert!(expected.args_note.is_none() || expected.args_note.as_deref().is_some_and(|note| !note.is_empty()));
    }
    Ok(())
}

#[test]
fn every_reference_rejection_is_refused_here_too() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.rejections.len(), 6);
    for rejection in &fixture.rejections {
        assert!(!rejection.reference_error_message.is_empty(), "{}", rejection.name);
        assert!(!rejection.note.is_empty(), "{}", rejection.name);
        let base = builder(&fixture)?;
        let refused = match rejection.name.as_str() {
            "no_backers_trait_with_backers" => matches!(
                base.configuration(vec![ConfigurationTrait::NoBackers])
                    .backers(vec!["a backer".to_owned()])
                    .backer_threshold(0)
                    .build(),
                Err(RegistryError::BackersForbiddenByConfiguration { count: 1 })
            ),
            "duplicate_backers" => matches!(
                base.backers(vec!["a backer".to_owned(), "a backer".to_owned()])
                    .backer_threshold(0)
                    .build(),
                Err(RegistryError::DuplicateBacker { index: 1 })
            ),
            "zero_toad_with_backers" => matches!(
                base.backers(vec!["a backer".to_owned()]).backer_threshold(0).build(),
                Err(RegistryError::InvalidBackerThreshold {
                    threshold: 0,
                    backers: 1
                })
            ),
            "toad_without_backers" => matches!(
                base.backer_threshold(1).build(),
                Err(RegistryError::InvalidBackerThreshold {
                    threshold: 1,
                    backers: 0
                })
            ),
            "toad_above_backer_count" => matches!(
                base.backers(vec!["a backer".to_owned()]).backer_threshold(2).build(),
                Err(RegistryError::InvalidBackerThreshold {
                    threshold: 2,
                    backers: 1
                })
            ),
            // The reference's crash on a non-digestive code has no equivalent input: the
            // derivation here is fixed to the only usable value.
            "basic_derivation_code" => true,
            other => return Err(format!("unknown rejection case {other:?}").into()),
        };
        assert!(refused, "{} was accepted", rejection.name);
    }
    Ok(())
}

#[test]
fn the_reference_quirks_hold_and_the_divergences_are_deliberate() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;

    // The NaN threshold: pinned from the reference, unrepresentable here.
    assert_eq!(quirks.non_numeric_toad_emits_nan.backer_threshold, "NaN");
    assert!(quirks.non_numeric_toad_emits_nan.raw.contains("\"bt\":\"NaN\""));
    assert_ne!(quirks.non_numeric_toad_emits_nan.note, "");
    assert_ne!(quirks.non_numeric_toad_emits_nan.rust_decision, "");

    // The string coercion: "1" and 1 build the same event upstream; only u32 exists here.
    assert!(quirks.string_toad_is_coerced.identical);
    assert_ne!(quirks.string_toad_is_coerced.note, "");
    assert_ne!(quirks.string_toad_is_coerced.rust_decision, "");

    // Unvalidated backers are the pinned vector itself; the unvalidated issuer is refused here.
    assert_ne!(quirks.backers_are_unvalidated.note, "");
    assert_ne!(quirks.backers_are_unvalidated.rust_decision, "");
    assert!(quirks.issuer_is_unvalidated.accepted);
    assert!(quirks.issuer_is_unvalidated.pre.starts_with('E'));
    assert_ne!(quirks.issuer_is_unvalidated.note, "");
    assert_ne!(quirks.issuer_is_unvalidated.rust_decision, "");
    assert!(IdentifierPrefix::from_qb64("not an identifier").is_err());

    // The random-nonce default: shape only, owned by Roadmap 6.4.
    assert_eq!(fixture.random_nonce_shape.length, 44);
    assert_eq!(fixture.random_nonce_shape.code, "A");
    assert_ne!(fixture.random_nonce_shape.note, "");
    Ok(())
}
